ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/genome/species/stoop_railing.json': '8f8d7708a7543169'}
EDITS = {'zoo_keeper/genome/species/stoop_railing.json': [('lines 6-6', '    "notes": "Factory roadmap 240, the walker\'s calls of 2026-10-13 (\'3 risers, concrete, railings both sides -- build the railings\') on the comps\' rowhouse street: \'three or four steps up to each door, with iron railings\'. REFERENCE: a black painted wrought-iron stoop railing -- square posts, a flat-bar top rail, a bottom rail, square pickets -- one a side, along the landing and down the steps. The residential code gives the numbers where a three-riser stoop does not require one (IRC R311.7.8: a handrail 34-38 in over the nosings, drawn at 36; R312.1.3: pickets at 4 in clear). Two forms drawn from the slot\'s box alone: level and flight (`core/stoop_railing_forms.py`). No collision: Deli Counter writes it with the stoop\'s. A STAIR\'S BALUSTRADE TOO (1.128.0): the walker, walking cold run 9386, of an office stair\'s guards -- solid wood boxes round its hole -- \\"the walling/railing doesn\'t loook natural yet\\". Deli Counter >= 0.268.0 stands a stair hole\'s guards as this species\' level form, so the width reaches a hole edge\'s length (8 m) and the depth a guard\'s (0.12 m, the top rail as wide as the guard); a run longer than one bay stands a post at least every `POST_BAY` (2.0 m, a newel\'s spacing on a long balustrade)."\n', '    "notes": "Factory roadmap 240, the walker\'s calls of 2026-10-13 (\'3 risers, concrete, railings both sides -- build the railings\') on the comps\' rowhouse street: \'three or four steps up to each door, with iron railings\'. REFERENCE: a black painted wrought-iron stoop railing -- square posts, a flat-bar top rail, a bottom rail, square pickets -- one a side, along the landing and down the steps. The residential code gives the numbers where a three-riser stoop does not require one (IRC R311.7.8: a handrail 34-38 in over the nosings, drawn at 36; R312.1.3: pickets at 4 in clear). Two forms drawn from the slot\'s box alone: level and flight (`core/stoop_railing_forms.py`). No collision: Deli Counter writes it with the stoop\'s. A STAIR\'S BALUSTRADE TOO (1.128.0): the walker, walking cold run 9386, of an office stair\'s guards -- solid wood boxes round its hole -- \\"the walling/railing doesn\'t loook natural yet\\". Deli Counter >= 0.268.0 stands a stair hole\'s guards as this species\' level form, so the width reaches a hole edge\'s length (8 m) and the depth a guard\'s (0.12 m, the top rail as wide as the guard); a run longer than one bay stands a post at least every `POST_BAY` (2.0 m, a newel\'s spacing on a long balustrade). A STOREY\'S FLIGHT (1.129.0): Deli Counter >= 0.269.0 stands this species\' flight form along a switchback\'s upper flight, its box the flight\'s rise plus `RAIL_H` -- a 3.6 m storey asks 4.51 m -- so the height reaches 6.0 m (a 5.0 m storey and its rail). Planning reads no limit from the genome, so no railing built before moves."\n'), ('lines 21-21', '      "max": 1.6,\n', '      "max": 6.0,\n')]}
NEW_FILES = {'tests/test_rail_flight_height.py': '"""A storey\'s flight (1.129.0): `stoop_railing`\'s flight form, as tall as a storey\'s rise and its rail, plans as the\nspecies. For a switchback\'s upper flight (the walker\'s walk of cold run 9386, finding 6). FAILS ON 1.128.0."""\nfrom zoo_keeper.core import kit\n\n\ndef test_a_storeys_flight_rail_plans_as_the_species():\n    slot = {"slot_id": "stair_rake_0", "role": "prop", "size_mod": "full", "style": 1, "material": "metal_painted",\n            "species": "stoop_railing", "form": "flight",\n            "fit": {"dims": [5.2339, 0.05, 3.6 + 0.9144], "pivot": "center", "collision": "none"}}\n    plan = kit.plan_kit({"building_id": "t", "slots": [slot]}, theme="delco_1997", style=1)\n    assert plan["modules"][0]["species"] == "stoop_railing", plan.get("species_fallbacks")\n    assert not plan.get("species_fallbacks"), plan["species_fallbacks"]\n'}
CHANGELOG = '## [1.129.0] - `stoop_railing`\'s flight form reaches a storey\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 6), of the office\'s\nswitchback: the block over its upper flight, "the walling/railing doesn\'t loook natural yet". Deli Counter >= 0.269.0\nstands this species\' flight form along that flight\'s inner edge, its box the flight\'s rise plus the rail.\n\n### Changed\n- **The genome\'s height reaches 6.0 m** (was 1.6): a 3.6 m storey\'s flight asks 4.51 m, a 5.0 m storey\'s 5.91. The\n  office\'s, 5.2339 x 0.05 x 4.5144 m, builds as the species -- a raking rail at 34.6 degrees, 44 pickets sheared to\n  its pitch, one mesh of 282 faces. Planning reads no limit from the genome: 126 stoop railings plan vertex for vertex\n  as before (the factory\'s `patches/zoo_rail_flight_height/stoop_unchanged.out.txt`).\n\n### Tests\n- `tests/test_rail_flight_height.py` (new): a storey\'s flight rail plans as the species, failing on 1.128.0.\n\n'
OLD_VERSION, NEW_VERSION = '1.128.0', '1.129.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
